class Solution { public boolean possibleBipartition(int n,int[][] dislikes){List<Integer>[] graph=new List[n+1];for(int i=1;i<=n;i++)graph[i]=new ArrayList<>();for(int[] edge:dislikes){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}int[] color=new int[n+1];for(int start=1;start<=n;start++)if(color[start]==0){Queue<Integer> queue=new ArrayDeque<>();queue.offer(start);color[start]=1;while(!queue.isEmpty()){int node=queue.poll();for(int next:graph[node])if(color[next]==0){color[next]=-color[node];queue.offer(next);}else if(color[next]==color[node])return false;}}return true;} }
